public class Finding { public string id {get;set;} public string text {get;set;} public string evidence {get;set;} public bool verified {get;set;} }
public class Recommendation { public string id {get;set;} public string action {get;set;} public string owner {get;set;} public string due {get;set;} public List<string> findingIds {get;set;} }
public class Draft {
 public string id {get;set;} public int revision {get;set;} public string templateHash {get;set;} public string title {get;set;} public string county {get;set;} public string term {get;set;} public string releaseDate {get;set;} public string updated {get;set;} public int current {get;set;}
 public Dictionary<string,string> answers {get;set;} public List<Finding> findings {get;set;} public List<Recommendation> recommendations {get;set;}
}
public class Section {public string id {get;set;} public string title {get;set;} public List<string> guidance {get;set;} public bool optional {get;set;} }
public class Template {public string hash {get;set;} public List<Section> sections {get;set;} public List<string> instructions {get;set;} }
public class Result {public bool ok {get;set;} public string error {get;set;} public Template template {get;set;} public Draft draft {get;set;} public List<Draft> drafts {get;set;} public string data {get;set;} }

public sealed class Engine {
 public readonly string DataDir;
 readonly JavaScriptSerializer json=new JavaScriptSerializer {MaxJsonLength=16*1024*1024};
 public Engine(string dir){DataDir=Path.GetFullPath(dir);}
 public Result Call(string op,object body=null) {
  Dictionary<string,object> q=new Dictionary<string,object>{{"op",op},{"dir",DataDir}};
  if(body is Draft)q["draft"]=body;else if(body!=null)q[op=="import"?"content":"id"]=body;
  ProcessStartInfo start=new ProcessStartInfo(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"ReportEngine.exe"));
  start.UseShellExecute=false;start.CreateNoWindow=true;start.RedirectStandardInput=true;start.RedirectStandardOutput=true;start.RedirectStandardError=true;start.StandardOutputEncoding=Encoding.UTF8;
  using(Process p=Process.Start(start)) {
   // Write UTF-8 explicitly: redirected Console encodings differ between Windows versions.
   byte[] request=Encoding.UTF8.GetBytes(json.Serialize(q));p.StandardInput.BaseStream.Write(request,0,request.Length);p.StandardInput.Close();
   System.Threading.Tasks.Task<string> output=p.StandardOutput.ReadToEndAsync();System.Threading.Tasks.Task<string> error=p.StandardError.ReadToEndAsync();
   if(!p.WaitForExit(20000)){p.Kill();throw new IOException("The local engine timed out. Your previous saved draft is unchanged.");}
   string text=output.Result;if(p.ExitCode!=0)throw new IOException("The local engine could not complete the operation. "+error.Result);
   Result result=json.Deserialize<Result>(text);if(result==null||!result.ok)throw new IOException(result==null?"The local engine returned an invalid response.":result.error);return result;
  }
 }
}

