  TableLayoutPanel root=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=2,RowCount=2,Padding=new Padding(18)};root.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,245));root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,72));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));
  Label brand=new Label{Text="REPORT INTERVIEW",Font=new Font("Segoe UI",17,FontStyle.Bold),ForeColor=teal,Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleLeft};root.Controls.Add(brand,0,0);
  FlowLayoutPanel toolbar=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.LeftToRight,Padding=new Padding(0,14,0,0)};AddButton(toolbar,"New report",delegate{Guard(NewDraft);});AddButton(toolbar,"Open draft…",delegate{Guard(OpenDraft);});AddButton(toolbar,"Import draft…",delegate{Guard(ImportDraft);});AddButton(toolbar,"Save draft",delegate{Guard(delegate{Save();});});root.Controls.Add(toolbar,1,0);
  steps.Dock=DockStyle.Fill;steps.BorderStyle=BorderStyle.FixedSingle;steps.Font=new Font("Segoe UI",10);steps.ItemHeight=29;steps.IntegralHeight=false;steps.AccessibleName="Report sections";steps.Items.Add("1. Report details");for(int i=0;i<template.sections.Count;i++)steps.Items.Add((i+2)+". "+template.sections[i].title);steps.Items.Add("14. Review and export");steps.SelectedIndexChanged+=delegate {if(!rendering&&steps.SelectedIndex>=0)Guard(delegate{Navigate(steps.SelectedIndex);});};root.Controls.Add(steps,0,1);
