 void Guard(Action action){try{action();}catch(Exception ex){ShowError(ex);}}
 void ShowError(Exception ex){status.Text="Operation failed — keep this window open if you have unsaved changes.";if(testMode)throw ex;MessageBox.Show(this,ex.Message,"Report Interview",MessageBoxButtons.OK,MessageBoxIcon.Warning);}
 static bool Blank(string s){return String.IsNullOrWhiteSpace(s);}
 static string ID(){return Guid.NewGuid().ToString("N");}
 void Normalize(){if(draft.answers==null)draft.answers=new Dictionary<string,string>();if(draft.findings==null)draft.findings=new List<Finding>();if(draft.recommendations==null)draft.recommendations=new List<Recommendation>();foreach(Recommendation r in draft.recommendations)if(r.findingIds==null)r.findingIds=new List<string>();}
 void Changed(){if(rendering)return;dirty=true;status.Text="Unsaved changes";autosave.Stop();autosave.Start();}
 public void NewDraft(){Save();draft=engine.Call("new").draft;Normalize();step=0;dirty=false;Render();}
 public void Save(){autosave.Stop();if(draft==null||!dirty)return;Draft saved=engine.Call("save",draft).draft;draft.revision=saved.revision;draft.updated=saved.updated;dirty=false;status.Text="Saved locally at "+DateTime.Now.ToShortTimeString();}
 public void Navigate(int index){if(draft==null||index<0||index>13||changing)return;changing=true;int old=step;try{Save();step=index;draft.current=step;Changed();Render();}catch{rendering=true;steps.SelectedIndex=old;rendering=false;throw;}finally{changing=false;}}
 void OpenDraft(){Save();List<Draft> all=engine.Call("list").drafts??new List<Draft>();if(all.Count==0){MessageBox.Show(this,"No saved drafts yet. Choose New report, or import a JSON draft from the browser version.","Open saved draft");return;}using(Form dialog=new Form{Text="Open saved draft",Size=new Size(700,420),StartPosition=FormStartPosition.CenterParent,MinimizeBox=false,MaximizeBox=false}){ListBox list=new ListBox{Dock=DockStyle.Fill,Font=Font,AccessibleName="Saved drafts",HorizontalScrollbar=true};foreach(Draft d in all)list.Items.Add((Blank(d.title)?"Untitled report":d.title)+" — "+d.updated);list.SelectedIndex=0;Button open=new Button{Text="Open",Dock=DockStyle.Bottom,Height=40,DialogResult=DialogResult.OK};list.DoubleClick+=delegate{dialog.DialogResult=DialogResult.OK;dialog.Close();};dialog.Controls.Add(list);dialog.Controls.Add(open);dialog.AcceptButton=open;if(dialog.ShowDialog(this)==DialogResult.OK&&list.SelectedIndex>=0)LoadDraft(all[list.SelectedIndex].id);}}
 public void LoadDraft(string id){Save();draft=engine.Call("get",id).draft;Normalize();step=Math.Max(0,Math.Min(13,draft.current));dirty=false;Render();status.Text="Resumed saved draft";}
 void ImportDraft(){Save();using(OpenFileDialog dialog=new OpenFileDialog{Title="Import a saved report draft from the browser version",Filter="Report draft JSON (*.json)|*.json|All files (*.*)|*.*",CheckFileExists=true}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;ImportContent(File.ReadAllText(dialog.FileName,Encoding.UTF8));}}
 public void ImportContent(string json){Save();draft=engine.Call("import",json).draft;Normalize();step=Math.Max(0,Math.Min(13,draft.current));dirty=false;Render();status.Text="Imported a copy of the draft; the original file was not changed.";}
 static void SetupButton(Button b){b.AutoSize=true;b.MinimumSize=new Size(95,34);b.Padding=new Padding(7,3,7,3);b.UseVisualStyleBackColor=true;}
 Button AddButton(Control parent,string text,Action action){Button b=new Button{Text=text,AccessibleName=text};SetupButton(b);b.Click+=delegate{action();};parent.Controls.Add(b);return b;}
 void ResizeFields(){int width=Math.Max(200,fields.ClientSize.Width-36);foreach(Control c in fields.Controls)c.Width=width;prompt.MaximumSize=new Size(Math.Max(200,editor.ClientSize.Width-54),0);}
 Label Note(Control parent,string text,bool bold=false){Label l=new Label{Text=text,AutoSize=true,MaximumSize=new Size(620,0),Margin=new Padding(0,9,0,7),Font=bold?new Font(Font,FontStyle.Bold):Font};parent.Controls.Add(l);return l;}
 TextBox Field(Control parent,string label,string value,Action<string> set,bool multiline=false){Note(parent,label,true);TextBox input=new TextBox{Text=value??"",Multiline=multiline,AcceptsReturn=multiline,ScrollBars=multiline?ScrollBars.Vertical:ScrollBars.None,Height=multiline?130:30,Width=600,AccessibleName=label,Margin=new Padding(0,0,0,9),BorderStyle=BorderStyle.FixedSingle};input.TextChanged+=delegate{set(input.Text);Changed();};parent.Controls.Add(input);return input;}
 FlowLayoutPanel Card(string title){FlowLayoutPanel c=new FlowLayoutPanel{AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,BorderStyle=BorderStyle.FixedSingle,BackColor=Color.FromArgb(247,250,246),Padding=new Padding(12),Margin=new Padding(0,8,0,16)};Note(c,title,true);c.SizeChanged+=delegate{foreach(Control child in c.Controls){if(child is Button)continue;child.Width=Math.Max(100,c.Width-30);Label l=child as Label;if(l!=null)l.MaximumSize=new Size(child.Width,0);}};fields.Controls.Add(c);return c;}
 void Guidance(Section s){if(s.guidance==null||s.guidance.Count==0)return;TextBox text=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Height=145,Width=600,Visible=false,Text=String.Join(Environment.NewLine+Environment.NewLine,s.guidance),AccessibleName="Original template guidance",TabStop=true,BackColor=Color.FromArgb(239,244,237)};Button toggle=AddButton(fields,"Show template guidance",delegate{text.Visible=!text.Visible;ResizeFields();});toggle.Click+=delegate{toggle.Text=text.Visible?"Hide template guidance":"Show template guidance";};fields.Controls.Add(text);}
 string Answer(string id){string value;return draft.answers.TryGetValue(id,out value)?value:"";}
 string Prompt(string id){switch(id){case "summary":return "Summarize the main issues, supported findings and proposed actions. Aim for one page.";case "glossary":return "Define terms unfamiliar to the public. Use one term and definition per paragraph.";case "background":return "Explain why the topic was selected and provide supported context.";case "methodology":return "Describe documents, site visits and interview categories in narrative form. Protect confidential identities.";case "discussion":return "Describe verified information supporting your findings. Add nested headings or visuals in Word after export.";case "findings":return "Record conclusions supported by evidence. Evidence notes stay in the draft and are not published.";case "recommendations":return "State who should do what and by when. Link each recommendation to its supporting findings.";case "required-responses":return "Enter approved recipients, deadlines and F/R references. Check the template guidance and consult your legal advisor.";case "invited-responses":return "Enter invited recipients, F/R references and requested response dates.";case "bibliography":return "List public sources with enough information to locate each one.";case "appendix":return "Enter verified supporting text. Add accessible attachments in Word after export.";case "disclaimer":return "Enter approved disclaimer language only when applicable.";default:return "";}}
 void Render(){rendering=true;SuspendLayout();fields.SuspendLayout();try{while(fields.Controls.Count>0)fields.Controls[0].Dispose();saveMenu.Enabled=draft!=null;exportMenu.Enabled=draft!=null;steps.Enabled=draft!=null;previous.Enabled=draft!=null&&step>0;next.Visible=draft!=null&&step<13;if(draft==null){heading.Text="A clear path through your report";progress.Text="Native Windows • Local files • No AI";prompt.Text="Start a report, resume a saved draft, or import a draft from the browser version.";Note(fields,"The interview follows your revised accessible Word template. Only author-entered report content is exported. Required sections and evidence verification are checked before export.");Note(fields,"Drafts save automatically to your Windows user profile. Keep backups according to your organization’s policy. No browser, network connection, Go installation or Python installation is needed.");AddButton(fields,"Start a new report",delegate{Guard(NewDraft);});AddButton(fields,"Open saved draft…",delegate{Guard(OpenDraft);});AddButton(fields,"Import browser-version draft…",delegate{Guard(ImportDraft);});return;}
  steps.SelectedIndex=step;progress.Text="Step "+(step+1)+" of 14";Text="Report Interview — "+(Blank(draft.title)?"Untitled report":draft.title);
  if(step==0){heading.Text="Report details";prompt.Text="Enter approved report details. Do not fill missing information with guesses.";Field(fields,"Report title",draft.title,delegate(string v){draft.title=v;});Field(fields,"County",draft.county,delegate(string v){draft.county=v;});Field(fields,"Grand jury term",draft.term,delegate(string v){draft.term=v;});Field(fields,"Approved public release date",draft.releaseDate,delegate(string v){draft.releaseDate=v;});Note(fields,"Separate paragraphs with a blank line. Your entries are used verbatim; the application does not invent or verify facts.");}
  else if(step==13){RenderReview();}
  else{Section s=template.sections[step-1];heading.Text=s.title;progress.Text+=s.optional?" • Optional":"";prompt.Text=Prompt(s.id);Guidance(s);if(s.id=="findings")RenderFindings();else if(s.id=="recommendations")RenderRecommendations();else{TextBox text=Field(fields,s.optional?"Report text — leave blank to omit this section":"Report text",Answer(s.id),delegate(string v){draft.answers[s.id]=v;},true);text.Height=260;if(s.id=="required-responses"||s.id=="invited-responses")Note(fields,"F/R references in this section are entered manually. Recheck them after findings or recommendations are added or removed.");}}
 }finally{ResizeFields();fields.ResumeLayout(true);ResumeLayout(true);rendering=false;}}
 void RenderFindings(){for(int i=0;i<draft.findings.Count;i++){Finding item=draft.findings[i];FlowLayoutPanel c=Card("F"+(i+1));CheckBox verified=new CheckBox{Text="I have checked this finding against its evidence.",Checked=item.verified,AutoSize=true,AccessibleName="Verify finding F"+(i+1)};Field(c,"Finding F"+(i+1),item.text,delegate(string v){item.text=v;item.verified=false;verified.Checked=false;},true);Field(c,"Evidence reference for F"+(i+1),item.evidence,delegate(string v){item.evidence=v;item.verified=false;verified.Checked=false;},true);verified.CheckedChanged+=delegate{item.verified=verified.Checked;Changed();};c.Controls.Add(verified);AddButton(c,"Remove F"+(i+1),delegate{Guard(delegate{if(draft.recommendations.Any(r=>r.findingIds.Contains(item.id)))throw new IOException("Unlink this finding from its recommendations before removing it.");if(!testMode&&MessageBox.Show(this,"Remove this finding? Subsequent F numbers will change.","Remove finding",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;draft.findings.Remove(item);Changed();Render();});});}if(draft.findings.Count==0)Note(fields,"No findings entered yet.");AddButton(fields,"Add finding",delegate{AddFinding();});}
 public void AddFinding(){draft.findings.Add(new Finding{id=ID(),text="",evidence=""});Changed();Render();}
 void RenderRecommendations(){for(int i=0;i<draft.recommendations.Count;i++){Recommendation item=draft.recommendations[i];FlowLayoutPanel c=Card("R"+(i+1));Field(c,"Responsible official or entity for R"+(i+1),item.owner,delegate(string v){item.owner=v;});Field(c,"Recommended action R"+(i+1),item.action,delegate(string v){item.action=v;},true);Field(c,"Deadline or timing for R"+(i+1),item.due,delegate(string v){item.due=v;});Note(c,"Supporting findings",true);for(int j=0;j<draft.findings.Count;j++){Finding find=draft.findings[j];CheckBox link=new CheckBox{Text="F"+(j+1)+": "+(Blank(find.text)?"Not entered":find.text),Checked=item.findingIds.Contains(find.id),AutoSize=false,Height=50,AccessibleName="Link R"+(i+1)+" to F"+(j+1)};link.CheckedChanged+=delegate{if(link.Checked){if(!item.findingIds.Contains(find.id))item.findingIds.Add(find.id);}else item.findingIds.Remove(find.id);Changed();};c.Controls.Add(link);}if(draft.findings.Count==0)Note(c,"Add findings before linking this recommendation.");AddButton(c,"Remove R"+(i+1),delegate{if(!testMode&&MessageBox.Show(this,"Remove this recommendation? Subsequent R numbers will change.","Remove recommendation",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;draft.recommendations.Remove(item);Changed();Render();});}AddButton(fields,"Add recommendation",delegate{AddRecommendation();});}
 public void AddRecommendation(){draft.recommendations.Add(new Recommendation{id=ID(),action="",owner="",due="",findingIds=new List<string>()});Changed();Render();}
 public List<KeyValuePair<int,string>> Missing(){List<KeyValuePair<int,string>> missing=new List<KeyValuePair<int,string>>();Action<int,string> add=delegate(int n,string s){missing.Add(new KeyValuePair<int,string>(n,s));};if(draft==null){add(0,"Start or open a report.");return missing;}if(Blank(draft.title))add(0,"Report title");if(Blank(draft.county))add(0,"County");if(Blank(draft.term))add(0,"Grand jury term");if(Blank(draft.releaseDate))add(0,"Approved public release date");for(int i=0;i<template.sections.Count;i++){string id=template.sections[i].id;if(new[]{"summary","background","methodology","discussion","required-responses"}.Contains(id)&&Blank(Answer(id)))add(i+1,template.sections[i].title+": report text");}if(draft.findings.Count==0)add(6,"At least one finding");for(int i=0;i<draft.findings.Count;i++){Finding f=draft.findings[i];if(Blank(f.text)||Blank(f.evidence)||!f.verified)add(6,"F"+(i+1)+": text, evidence reference and author verification");}if(draft.recommendations.Count==0)add(7,"At least one recommendation");for(int i=0;i<draft.recommendations.Count;i++){Recommendation r=draft.recommendations[i];if(Blank(r.action)||Blank(r.owner)||Blank(r.due)||r.findingIds.Count==0||r.findingIds.Any(id=>!draft.findings.Any(f=>f.id==id)))add(7,"R"+(i+1)+": action, owner, timing and valid finding link");}return missing;}
 void RenderReview(){heading.Text="Review and export";prompt.Text="Check completeness, factual support and accessibility before exporting.";List<KeyValuePair<int,string>> missing=Missing();Note(fields,"Required information",true);if(missing.Count>0){Note(fields,"Missing items — double-click an item to go to its section.");ListBox list=new ListBox{Height=Math.Min(280,50+missing.Count*26),IntegralHeight=false,AccessibleName="Missing required information",HorizontalScrollbar=true};foreach(var item in missing)list.Items.Add(item.Value);list.DoubleClick+=delegate{if(list.SelectedIndex>=0)Guard(delegate{Navigate(missing[list.SelectedIndex].Key);});};fields.Controls.Add(list);}else Note(fields,"All required fields are complete. This confirms entry, not factual accuracy.");Note(fields,"Finding and recommendation links",true);for(int i=0;i<draft.findings.Count;i++){Finding f=draft.findings[i];string linked=String.Join(", ",draft.recommendations.Select((r,j)=>new{r,j}).Where(x=>x.r.findingIds.Contains(f.id)).Select(x=>"R"+(x.j+1)));Note(fields,"F"+(i+1)+" → "+(linked==""?"No linked recommendation":linked)+": "+f.text);}Note(fields,"Export uses the template’s automatic F/R styles and clickable recommendation-to-finding links. Evidence notes stay in the saved draft. Manually entered F/R references in responses still need review.");Note(fields,"This version exports narrative text. Add structured subheadings, accessible tables, figures and attachments in Word. Run Word’s Accessibility Checker and arrange review of the final public PDF.");Button export=AddButton(fields,"Save and export Word report…",delegate{Guard(Export);});export.Enabled=missing.Count==0;}
 void Export(){if(draft==null)return;Save();if(Missing().Count>0){Navigate(13);status.Text="Complete the missing required information before exporting.";return;}using(SaveFileDialog dialog=new SaveFileDialog{Title="Export Word report",Filter="Word document (*.docx)|*.docx",DefaultExt="docx",AddExtension=true,OverwritePrompt=true,FileName=SafeFilename(draft.title)+".docx"}){if(dialog.ShowDialog(this)!=DialogResult.OK)return;ExportTo(dialog.FileName);MessageBox.Show(this,"The Word report has been exported.\n\nReview numbering, links and layout in Word. Complete the accessibility review before publication.","Export complete",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
 static string SafeFilename(string name){foreach(char c in Path.GetInvalidFileNameChars())name=name.Replace(c,'-');name=name.Trim().TrimEnd('.');return name.Length==0?"Report":name.Substring(0,Math.Min(name.Length,120));}
 public void ExportTo(string path){Save();byte[] bytes=Convert.FromBase64String(engine.Call("export",draft.id).data);string temp=path+"."+ID()+".tmp";try{File.WriteAllBytes(temp,bytes);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}status.Text="Word report exported. Review in Word before publication.";}
 void ShowGuidance(){using(Form dialog=new Form{Text="Template publication guidance",Size=new Size(820,650),StartPosition=FormStartPosition.CenterParent}){TextBox text=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Dock=DockStyle.Fill,Font=Font,Text=String.Join(Environment.NewLine+Environment.NewLine,template.instructions),AccessibleName="Original publication guidance"};dialog.Controls.Add(text);dialog.ShowDialog(this);}}
 public Draft CurrentDraft {get{return draft;}}
 public Control FindAccessible(string name){return Descendants(this).First(c=>c.AccessibleName==name);}
 static IEnumerable<Control> Descendants(Control c){foreach(Control child in c.Controls){yield return child;foreach(Control nested in Descendants(child))yield return nested;}}
 public void CaptureScreenshot(string path){using(Bitmap image=new Bitmap(Width,Height)){DrawToBitmap(image,new Rectangle(Point.Empty,Size));image.Save(path,System.Drawing.Imaging.ImageFormat.Png);}}
}

static class Program {
 [STAThread] static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);try{if(args.Length==2&&args[0]=="--self-test")return SelfTest(Path.GetFullPath(args[1]));string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ReportInterview","Drafts");bool first;using(Mutex mutex=new Mutex(true,"Local\\ReportInterviewDesktop."+Environment.UserName,out first)){if(!first){MessageBox.Show("Report Interview is already running. Use its existing window.","Report Interview");return 0;}Application.Run(new ReportForm(dir));}return 0;}catch(Exception ex){if(args.Length>0){Console.Error.WriteLine(ex.ToString());if(args.Length==2&&args[0]=="--self-test")File.WriteAllText(Path.Combine(args[1],"FAIL.txt"),ex.ToString());return 1;}MessageBox.Show(ex.Message,"Report Interview could not start",MessageBoxButtons.OK,MessageBoxIcon.Error);return 1;}}
 static int SelfTest(string work){Directory.CreateDirectory(work);using(ReportForm f=new ReportForm(Path.Combine(work,"drafts"),true)){f.StartPosition=FormStartPosition.Manual;f.Location=new Point(-2500,-2500);f.Show();Application.DoEvents();f.NewDraft();if(f.Missing().Count<8)throw new Exception("Missing-section validation failed");Action<string,string> fill=delegate(string name,string value){((TextBox)f.FindAccessible(name)).Text=value;};fill("Report title","Synthetic desktop verification — café");fill("County","Test County");fill("Grand jury term","Test term");fill("Approved public release date","Test date");foreach(int index in new[]{1,3,4,5,8}){f.Navigate(index);fill("Report text","Synthetic test content for section "+index+".\r\n\r\nSecond paragraph.");}f.Navigate(6);f.AddFinding();fill("Finding F1","Synthetic finding.");fill("Evidence reference for F1","Synthetic evidence note.");((CheckBox)f.FindAccessible("Verify finding F1")).Checked=true;fill("Finding F1","Revised synthetic finding.");if(f.CurrentDraft.findings[0].verified)throw new Exception("Editing finding did not reset verification");((CheckBox)f.FindAccessible("Verify finding F1")).Checked=true;f.Navigate(7);f.AddRecommendation();fill("Responsible official or entity for R1","Test owner");fill("Recommended action R1","Test action");fill("Deadline or timing for R1","Test timing");((CheckBox)f.FindAccessible("Link R1 to F1")).Checked=true;f.Navigate(13);f.Save();if(f.Missing().Count!=0)throw new Exception("Complete report failed validation");string original=f.CurrentDraft.id;int revision=f.CurrentDraft.revision;f.LoadDraft(original);if(f.CurrentDraft.title!="Synthetic desktop verification — café"||f.CurrentDraft.revision!=revision)throw new Exception("Save/resume lost content");f.ExportTo(Path.Combine(work,"native-export.docx"));f.CaptureScreenshot(Path.Combine(work,"desktop-review.png"));f.Navigate(6);f.CaptureScreenshot(Path.Combine(work,"desktop-findings.png"));f.ImportContent(File.ReadAllText(Path.Combine(work,"drafts",original+".json")));if(f.CurrentDraft.id==original||f.CurrentDraft.title!="Synthetic desktop verification — café")throw new Exception("Import did not preserve a separate draft");if(!File.Exists(Path.Combine(work,"drafts",original+".json")))throw new Exception("Import removed original draft");f.Save();File.WriteAllText(Path.Combine(work,"PASS.txt"),"PASS: native controls, missing sections, verification reset, F/R links, UTF-8, save/resume, export and draft import. No browser or web server.");f.Close();}return 0;}
}
